import{_ as t,o as s,c as a,a5 as o}from"./chunks/framework.CQwNn0Y-.js";const g=JSON.parse('{"title":"架构设计","description":"","frontmatter":{},"headers":[],"relativePath":"docs/architecture.md","filePath":"docs/architecture.md","lastUpdated":1792245757000}'),d={name:"docs/architecture.md"};function n(c,e,r,l,i,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to “架构设计”">​</a></h1><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to “目录结构”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── crates/</span></span>
<span class="line"><span>│   ├── zenfile-core/     领域层，不依赖任何 UI 框架</span></span>
<span class="line"><span>│   │   ├── engine        目录枚举（FindFirstFileExW + 大目录取回优化）</span></span>
<span class="line"><span>│   │   ├── watch         ReadDirectoryChangesW 增量刷新（仅当前可见目录）</span></span>
<span class="line"><span>│   │   ├── transfer      自研传输引擎（见下）</span></span>
<span class="line"><span>│   │   ├── index         文件名索引</span></span>
<span class="line"><span>│   │   ├── clipboard     CF_HDROP 与资源管理器双向互通</span></span>
<span class="line"><span>│   │   ├── recycle       直接解析 $Recycle.Bin，不经由 COM</span></span>
<span class="line"><span>│   │   ├── drives        驱动器清单（Win32 直呼，不使用 WMI）</span></span>
<span class="line"><span>│   │   ├── network       网络驱动器与共享（MPR WNet* 系列）</span></span>
<span class="line"><span>│   │   ├── bulk          批量重命名规则（纯函数，不访问磁盘）</span></span>
<span class="line"><span>│   │   ├── plugin/ipc    插件运行时与帧协议</span></span>
<span class="line"><span>│   │   └── …             config/paths/hotkey/natural/columns/acl/ops…</span></span>
<span class="line"><span>│   ├── zenfile-app/      Win32 + GDI 自绘界面 → ZenFile.exe</span></span>
<span class="line"><span>│   └── zenfile-taskmgr/  任务管理模块</span></span></code></pre></div><p><code>zenfile-core</code> <strong>不依赖 UI 框架是一项硬性约束</strong>，确保更换渲染后端时内核代码无需修改。</p><h2 id="传输引擎" tabindex="-1">传输引擎 <a class="header-anchor" href="#传输引擎" aria-label="Permalink to “传输引擎”">​</a></h2><p>自研实现，<strong>未使用 <code>IFileOperation</code></strong>。按文件大小分三条路径：</p><table tabindex="0"><thead><tr><th>文件大小</th><th>实现路径</th><th>说明</th></tr></thead><tbody><tr><td>小于 8 MB</td><td><code>std::fs::copy</code></td><td>内核单流，实测吞吐最优</td></tr><tr><td>8 MB 至 256 MB</td><td>用户态分块并行</td><td>每个线程复用一个 8 MB 缓冲区</td></tr><tr><td>大于等于 256 MB</td><td><code>CopyFileExW</code> + 进度回调</td><td>转入内核路径，避免用户态双拷贝</td></tr></tbody></table><h3 id="为什么超大文件必须转内核" tabindex="-1">为什么超大文件必须转内核 <a class="header-anchor" href="#为什么超大文件必须转内核" aria-label="Permalink to “为什么超大文件必须转内核”">​</a></h3><p>早期版本把 4.7 GiB 文件切分成 64 块（每块 74 MB），数十个线程并发会产生 GB 级工作集并导致缓存颠簸，CPU 占用饱和而吞吐未同步提升（2.71 CPU-s/GiB）。</p><p>对照实测表明，单线程 <code>std::fs::copy</code> 相比 32 线程分块<strong>快 45%，CPU 消耗低 3.4 倍</strong>。</p><div class="tip custom-block"><p class="custom-block-title">根本原因</p><p>病根是「读入缓冲区再写出」这一<strong>用户态双拷贝路径本身</strong>，而非线程数量不足。 线程越多，只会让缓存颠簸越严重、CPU 越忙。</p></div><p>转入内核路径后的实测结果（4.7 GiB 真实 ISO，跨物理磁盘）：</p><ul><li>耗时由 7.44 s 降至 <strong>5.78 s</strong></li><li>CPU 消耗由 1.71 降至 <strong>0.376</strong> CPU-s/GiB</li><li>峰值线程数由 52 降至 <strong>21</strong></li></ul><p>已追平 Windows 资源管理器（5.89 s）。</p><h3 id="三个踩过一次的坑" tabindex="-1">三个踩过一次的坑 <a class="header-anchor" href="#三个踩过一次的坑" aria-label="Permalink to “三个踩过一次的坑”">​</a></h3><div class="danger custom-block"><p class="custom-block-title"><code>PROGRESS_CONTINUE = 0</code>，<code>PROGRESS_CANCEL = 1</code></p><p>写反 = 第一次回调就中止。整个传输直接静默失败。</p></div><div class="danger custom-block"><p class="custom-block-title"><code>CopyFileEx</code> 自己建目标文件</p><p>所以「预创建目标文件以避免碎片」的循环<strong>必须跳过 <code>Job::Big</code></strong>。 有单测 <code>kernel_files_are_never_preallocated</code> 守着这条。</p></div><div class="danger custom-block"><p class="custom-block-title"><code>Job::Big</code> 成功后不能走 <code>bump</code></p><p><code>progress_cb</code> 已经增量记过进度，再 <code>bump</code> 一次 = 速度显示翻倍。 <code>bump</code> 因此拆出了 <code>finish_file</code>。</p></div><p>另外：取消传输时 <code>CopyFileEx</code> 也会失败，<strong>必须先判 cancel 再传播错误</strong>， 否则用户看到的不是「已取消」而是「传输失败」。</p><h2 id="后台化" tabindex="-1">后台化 <a class="header-anchor" href="#后台化" aria-label="Permalink to “后台化”">​</a></h2><p>删除与批量重命名原先在 UI 线程同步执行，删除 20 000 个文件时窗口直接失去响应。</p><p>现已全部迁移至后台线程，结果经由 channel 与 <code>PostMessage</code> 回传主线程：</p><ul><li>删除进行期间主线程延迟 <strong>p50 0.0 ms、p95 4.4 ms</strong>，无卡死</li><li>期间可以切换目录、切换标签页</li></ul><div class="warning custom-block"><p class="custom-block-title">铁律</p><p><strong>worker 线程绝不碰 UI 状态。</strong> 后台只做纯计算与 I/O， 结果通过 <code>PostMessage</code> 回主线程 <code>drain</code>。</p></div><h2 id="目录扫描" tabindex="-1">目录扫描 <a class="header-anchor" href="#目录扫描" aria-label="Permalink to “目录扫描”">​</a></h2><p>冲突判定原本对每个条目调一次 <code>Path::exists()</code>（即 <code>GetFileAttributesW</code>）， 还得穿过杀软过滤驱动。10 万条目就是 10 万次。</p><p>改成 <code>ExistCache</code>：按目录缓存 <code>read_dir</code> 快照，大小写不敏感对齐 NTFS 语义。</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">10 万条目耗时</th></tr></thead><tbody><tr><td>naive（每条目 <code>Path::exists()</code>）</td><td style="text-align:right;">3.07 s</td></tr><tr><td><strong>生产实现</strong></td><td style="text-align:right;"><strong>0.233 s</strong>（13×）</td></tr><tr><td>纯枚举下界</td><td style="text-align:right;">0.033 s</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">基准里绝不能重抄一遍生产逻辑</p><p>曾经 <code>bench_dir</code> 的 engine 臂抄了一份简化版实现，测出「86 倍」， 而生产代码只优化了一半——<strong>优化只落地了一半，数字却是按全量算的</strong>。</p><p>现在 benchmark 的 engine 臂直接调 <code>pub fn plan_only()</code>， 把「判定结果」和「怎么判定」分开，判错了能一眼看出是哪边。</p></div><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to “内存管理”">​</a></h2><ul><li><strong>不递归计算文件夹大小</strong>——属性页用后台线程 + 120ms 增量回传</li><li><strong>不递归监听目录</strong>——<code>ReadDirectoryChangesW</code> 只挂当前可见目录</li><li>驱动器清单走 Win32 直呼，<strong>不使用 WMI</strong></li><li>回收站直接解析 <code>$Recycle.Bin</code>，<strong>不经由 COM</strong></li></ul><h2 id="子进程与自启动" tabindex="-1">子进程与自启动 <a class="header-anchor" href="#子进程与自启动" aria-label="Permalink to “子进程与自启动”">​</a></h2><p>子进程一律 <code>CREATE_SUSPENDED</code> → 入 Job Object → <code>ResumeThread</code>， 杜绝「已跑起来才入组失败」的窗口期。</p><p>自启动用 <code>schtasks</code>，<strong>不用 <code>HKCU\\...\\Run</code></strong>。</p><h2 id="剪贴板" tabindex="-1">剪贴板 <a class="header-anchor" href="#剪贴板" aria-label="Permalink to “剪贴板”">​</a></h2><p><code>CF_HDROP</code> + <code>Preferred DropEffect</code>，与资源管理器双向互通。</p><p><code>CF_HDROP</code> 是双精度 DWORD 偏移表，单位<strong>字节</strong>不是字符，末尾双 NUL。</p><p><code>GlobalLock</code> / <code>GlobalSize</code> 在 <strong>kernel32</strong>，不在 user32。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><code>OpenClipboard</code> 必须<strong>重试</strong>——其他程序可能持有。实现里重试 12 次 × 15ms。 另外，粘贴逻辑<strong>不能「源 == 目标就跳过」</strong>，副本后缀是 <code>X - 副本</code>。</p></div><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><p>三层，加载顺序为后者覆盖前者，逐键深合并：</p><table tabindex="0"><thead><tr><th>层级</th><th>路径</th><th>优先级</th></tr></thead><tbody><tr><td>默认</td><td>编译进二进制的 <code>defaults.json</code></td><td>低</td></tr><tr><td>用户</td><td><code>%APPDATA%\\ZenFile\\settings.json</code></td><td>中</td></tr><tr><td>覆盖</td><td><code>%APPDATA%\\ZenFile\\settings.user.json</code></td><td><strong>最高</strong></td></tr></tbody></table><p>图形设置界面<strong>仅写入「用户层」</strong>，不会覆盖「覆盖层」。因此可以放一份 <code>settings.user.json</code> 锁定特定偏好，程序在任何情况下都不会将其覆盖。</p><p>写入采用原子方式（先写 <code>.tmp</code> 再重命名）；配置损坏时自动备份为 <code>.broken.bak</code> 并继续使用上层配置。</p><table tabindex="0"><thead><tr><th>用途</th><th>位置</th></tr></thead><tbody><tr><td>界面布局与菜单条目</td><td><code>%APPDATA%\\ZenFile\\ui_settings.json</code></td></tr><tr><td>文件名索引缓存</td><td><code>%LOCALAPPDATA%\\ZenFile\\index\\{盘符}.bin</code></td></tr><tr><td>插件</td><td>可执行文件同级的 <code>plugins/</code></td></tr></tbody></table><h2 id="热键" tabindex="-1">热键 <a class="header-anchor" href="#热键" aria-label="Permalink to “热键”">​</a></h2><p><code>VK_*</code> 虚拟键码 + <code>MOD_NOREPEAT</code>，<strong>禁 ASCII 字面量</strong>。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>快捷键处理只挂 <code>WM_KEYDOWN</code>。带 Alt 的组合要走 <code>WM_SYSKEYDOWN</code>—— 漏了会导致<strong>所有 Alt 组合快捷键全部失效</strong>（这个缺陷在性能测试中被发现并修复过）。</p></div>`,48)])])}const b=t(d,[["render",n]]);export{g as __pageData,b as default};
